In this section, we prove Theorem~\ref{main}. We shall assume that conditions \eqref{ass-a}-\eqref{ass-fg} hold.
In order to get information about existence, uniqueness and the boundary behavior of the solutions to \eqref{prob}, 
we convert the quasi-linear problem \eqref{prob} into a corresponding semi-linear
problem through a change of variable procedure involving the Cauchy problem for $g\in C^2((0,+\infty))\cap C([0,+\infty))$,
\begin{equation}
	\label{cauchy}
	\begin{cases}
g'(s)=\frac{1}{\sqrt{a(g(s))}},\quad \text{for $s>0$}, &\\
g(0)=0, & \\
\noalign{\vskip3pt}
g(s)>0, \quad\text{for $s>0$}. &
\end{cases}
\end{equation}
Due to the requirement $g>0$, the solutions of~\eqref{cauchy} are unique and solve $\int_0^{g(s)}\sqrt{a(\xi)}d\xi=s$, for $s>0$.
The solution is global for $s>0$ since $a$ is bounded away from zero.
This procedure was also followed in  \cite{GlasquII} in the framework of explosive solutions, although
there $g$ is $C^2$ around the origin and defined on ${\mathbb R$. Now, since $g\in C^2((0,+\infty))\cap C([0,+\infty))$
and it is strictly increasing, it is readily seen by a direct computation that 
$u\in C^2(\Omega)\cap C(\bar\Omega)$ is a positive solution to \eqref{prob} if and only if 
$v=g^{-1}(u)\in C^2(\Omega)\cap C(\bar\Omega)$ is a positive solution to 
$-\Delta v=h(v)$ in $\Omega$, where we have set $h(s):=f(g(s))/\sqrt{a(g(s))}$ for $s>0$.
Let us now obtain the asymptotic behavior of the solution $g$ to problem~\eqref{cauchy} as $s\to 0^+$ depending 
of the assigned asymptotic behavior of $a$ as $s\to 0^+$, given by~\eqref{ass-a}. For every $0\leq \mu<1$, we have 
\begin{equation}
	\label{gatzero}
\lim_{s\to 0^+}\frac{g(s)}{s^{\frac{1}{1-\mu}}}=(1-\mu)^{\frac{1}{1-\mu}} a_0^{\frac{1}{2(\mu-1)}}.      
\end{equation}
In fact, taking into account \eqref{cauchy}, by l'H\^ opital's rule we have
\begin{align*}
\lim_{s\to 0^+}\frac{g(s)}{s^{\frac{1}{1-\mu}}}&=(1-\mu)\lim_{s\to 0^+}\frac{g'(s)}{s^{\frac{\mu}{1-\mu}}}
=(1-\mu)\lim_{s\to 0^+}\frac{1}{s^{\frac{\mu}{1-\mu}}\sqrt{a(g(s))}} \\
& =(1-\mu)\lim_{s\to 0^+}\frac{g^\mu(s)}{s^{\frac{\mu}{1-\mu}}\sqrt{a(g(s))g^{2\mu}(s)}} =
\frac{(1-\mu)}{\sqrt{a_0}} \Big(\lim_{s\to 0^+}  \frac{g(s)}{s^{\frac{1}{1-\mu}}}\Big)^\mu,
\end{align*}
which yields the claim. Moreover, by virtue of~\eqref{ass-a}, \eqref{ass-f} and \eqref{gatzero}, we have
\begin{equation}
	\label{accat0}
\lim_{s\to 0^+}\frac{h(s)}{s^{\frac{\mu-\gamma}{1-\mu}}}=
\lim_{s\to 0^+} f(g(s))g(s)^{\gamma}\frac{1}{\sqrt{a(g(s))g(s)^{2\mu}}}
\Big[\frac{g(s)}{s^{\frac{1}{1-\mu}}}\Big]^{\mu-\gamma}=
f_0 a_0^{\frac{1-\gamma}{2(\mu-1)}}(1-\mu)^{-\frac{\gamma-\mu}{1-\mu}}.
\end{equation}
Observe also that, since $a(s)\sim a_\infty s^k$ as $s\to+\infty$
and $f(s)\sim f_\infty s^{-p}$ as $s\to+\infty$ for some $a_\infty,f_\infty>0$, $k\geq 0$ and $p>1$,
if $g$ still denotes the solution to \eqref{cauchy}, we have three facts:
	\begin{equation}
		\label{limzze}
		\int_1^{+\infty}\frac{f(g(s))}{\sqrt{a(g(s))}}ds<+\infty,  \quad
\lim_{s\to 0^+}\frac{f(g(s))}{\sqrt{a(g(s))}}=+\infty,\quad
\text{$s\mapsto \frac{f(g(s))}{\sqrt{a(g(s))}}$ is nonincreasing.}
	\end{equation} 
The first property follows immediately from the limit
\begin{equation*}
\lim_{s\to +\infty}\frac{g(s)}{s^{\frac 2{k+2}}}=\big(\frac{k+2} 2 \frac 1{\sqrt a_\infty} \big)^{\frac 2{k+2}},
\end{equation*}
which was proved in \cite{GlasquII}. The other properties follow by \eqref{accat0} and
\eqref{ass-fg}, respectively. By virtue of \eqref{gatzero} we now prove that, 
for every $\gamma>1$ and $0\leq \mu<1$, there holds
\begin{equation}
	\label{limfracintt}
\lim_{s\to 0^+}\frac{\int_{g(s)}^{+\infty} f(\xi)d\xi}{s^{\frac{1-\gamma}{1-\mu}}}=f_0 a_0^{\frac{\gamma-1}{2(1-\mu)}}(\gamma-1)^{-1}
(1-\mu)^{-\frac{\gamma-1}{1-\mu}}.
\end{equation}
In fact, since $\int_{g(s)}^{+\infty} f(\xi)d\xi\to +\infty$ for all $\gamma>1$, it follows
\begin{align*}
\lim_{s\to 0^+}\frac{\int_{g(s)}^{+\infty} f(\xi)d\xi}{s^{\frac{1-\gamma}{1-\mu}}}&=
\frac{\mu-1}{1-\gamma}\lim_{s\to 0^+}\frac{f(g(s))}{s^{\frac{\mu-\gamma}{1-\mu}}\sqrt{a(g(s))}}
=\frac{\mu-1}{1-\gamma}\lim_{s\to 0^+}\frac{f(g(s))g^\mu(s)}{s^{\frac{\mu-\gamma}{1-\mu}}\sqrt{a(g(s))g^{2\mu}(s)}} \\
& =\frac{\mu-1}{(1-\gamma)\sqrt{a_0}}\lim_{s\to 0^+}f(g(s))g^\gamma(s)
\lim_{s\to 0^+}\frac{g^{\mu-\gamma}(s)}{s^{\frac{\mu-\gamma}{1-\mu}}} \\
& =\frac{\mu-1}{(1-\gamma)}\frac{f_0}{\sqrt{a_0}}
\lim_{s\to 0^+}\frac{g^{\mu-\gamma}(s)}{s^{\frac{\mu-\gamma}{1-\mu}}} 
=\frac{\mu-1}{(1-\gamma)}\frac{f_0}{\sqrt{a_0}}
\Big(\lim_{s\to 0^+}\frac{g(s)}{s^{\frac{1}{1-\mu}}}\Big)^{\mu-\gamma} \\
& =f_0 a_0^{\frac{\gamma-1}{2(1-\mu)}}(\gamma-1)^{-1}
(1-\mu)^{-\frac{\gamma-1}{1-\mu}}.
\end{align*}
Now, for every $\ell\geq 0$, there exists a 
unique solution $\phi\in C([0,+\infty))\cap C^2((0,+\infty))$ of the problem
\begin{equation}
	\begin{cases}
	\label{asympt-prob}
	\displaystyle
\phi'(s)=\sqrt{\ell^2+2\int_{g(\phi(s))}^{+\infty}f(\xi)d\xi}, \qquad \text{for $s>0$}, & \\
\noalign{\vskip4pt}
\, \phi(0)=0, \quad \phi(s)>0, \qquad\text{for $s>0$}, & \\
\noalign{\vskip6pt}
\lim\limits_{s\to+\infty}\phi'(s)=\ell,\,\,\,\,  \lim\limits_{s\to+\infty}\phi(s)=+\infty. & 
\end{cases}
\end{equation}
To prove this, taking into account \eqref{limzze}, it is sufficient to apply \cite[Lemma 1.3]{zhangcheng}.
Notice that, in particular, the solutions to problem \eqref{asympt-prob} locally (namely for every fixed $a>0$) 
solve the second order problem
\begin{equation}
	\begin{cases}
	\label{asympt-prob-ii}
	\displaystyle
-\phi''(s)=\frac{f(g(\phi(s))}{\sqrt{a(g(\phi(s)))}}, \qquad & \text{for $0<s\leq a$}, \\
\noalign{\vskip4pt}
\, \phi(0)=0, \quad \phi(s)>0, & \text{for $0<s\leq a$}.
\end{cases}
\end{equation}
We can now prove that, for every $\gamma>1$, $0\leq\mu<1$ and $\ell\geq 0$, there holds
\begin{equation}
	\label{zerobeh}
\lim_{s\to 0^+}\frac{\phi(s)}{s^{\frac{2-2\mu}{1+\gamma-2\mu}}}=
\Big(\frac{1+\gamma-2\mu}{2-2\mu}\Big)^{\frac{2-2\mu}{1+\gamma-2\mu}}		
f_0^{\frac{1-\mu}{1+\gamma-2\mu}} a_0^{\frac{\gamma-1}{2(1+\gamma-2\mu)}}(\gamma-1)^{\frac{\mu-1}{1+\gamma-2\mu}} 
	(1-\mu)^{\frac{1-\gamma}{1+\gamma-2\mu}},
\end{equation}
where $\phi$ denotes the unique solution to \eqref{asympt-prob}. 
In fact, by l'H\^ opital's rule and \eqref{limfracintt}, we obtain
	\begin{align*}
	\lim_{s\to 0^+}\frac{\phi(s)}{s^{\frac{2-2\mu}{1+\gamma-2\mu}}} &=
	\lim_{s\to 0^+}\Big[\frac{\phi(s)^{\frac{1+\gamma-2\mu}{2-2\mu}}}{s}\Big]^{\frac{2-2\mu}{1+\gamma-2\mu}} 
	=\lim_{s\to 0^+}\Bigg[\frac{\phi(s)^{\frac{1+\gamma-2\mu}{2-2\mu}}}{
	\displaystyle\int_0^{\phi(s)}\frac{d\tau}{\sqrt{\ell^2+\int_{g(\tau)}^{+\infty}f(\xi)d\xi}}  }\Bigg]^{\frac{2-2\mu}{1+\gamma-2\mu}} \\
&=\Big(\frac{1+\gamma-2\mu}{2-2\mu}\Big)^{\frac{2-2\mu}{1+\gamma-2\mu}}
	\lim_{s\to 0^+}\Big[\phi(s)^{\frac{\gamma-1}{2-2\mu}}\sqrt{\ell^2+\int_{g(\phi(s))}^{+\infty}f(\xi)d\xi}\Big]^{\frac{2-2\mu}{1+\gamma-2\mu}}    \\
	&=\Big(\frac{1+\gamma-2\mu}{2-2\mu}\Big)^{\frac{2-2\mu}{1+\gamma-2\mu}}
		\lim_{s\to 0^+}\left(\frac{\ell^2+\int_{g(\phi(s))}^{+\infty}f(\xi)d\xi}{ \phi(s)^{\frac{1-\gamma}{1-\mu}} }\right)^{\frac{1-\mu}{1+\gamma-2\mu}}   \\
		&=\Big(\frac{1+\gamma-2\mu}{2-2\mu}\Big)^{\frac{2-2\mu}{1+\gamma-2\mu}}
			\lim_{s\to 0^+}\left(\frac{\int_{g(s)}^{+\infty}f(\xi)d\xi}{s^{\frac{1-\gamma}{1-\mu}} }\right)^{\frac{1-\mu}{1+\gamma-2\mu}}  \\
			\noalign{\vskip4pt}
		&=\Big(\frac{1+\gamma-2\mu}{2-2\mu}\Big)^{\frac{2-2\mu}{1+\gamma-2\mu}}		
		f_0^{\frac{1-\mu}{1+\gamma-2\mu}} a_0^{\frac{\gamma-1}{2(1+\gamma-2\mu)}}(\gamma-1)^{\frac{\mu-1}{1+\gamma-2\mu}} 
			(1-\mu)^{\frac{1-\gamma}{1+\gamma-2\mu}}.
	\end{align*}
We are now ready to conclude the proof 
of Theorem~\ref{main}. 
In light of \cite[Theorem 1.1]{craRabTar}, since $h(s)\to +\infty$ as $s\to 0^+$ by \eqref{limzze}
and $h$ is non-increasing for $s>0$ by \eqref{ass-fg}, there exists a unique positive solution $z\in C^2(\Omega)\cap C(\bar\Omega)$
to $-\Delta v=h(v)$. Then $g(z)\in C^2(\Omega)\cap C(\bar\Omega)$ is a positive solution to \eqref{prob}. Assume that
$u_1,u_2\in C^2(\Omega)\cap C(\bar\Omega)$, $u_1,u_2>0$ solve \eqref{prob}. Then $g^{-1}(u_1),g^{-1}(u_2)>0$ solve
$-\Delta v=h(v)$. By uniqueness, we deduce $g^{-1}(u_1)=g^{-1}(u_2)$, in turn yielding $u_1=u_2$. By virtue of 
\cite[Theorem 2.2 and Theorem 2.5]{craRabTar} for any solution $v$ of $-\Delta v=h(v)$
there exist four constants $\Lambda_1,\Lambda_2,\Lambda_3,\Lambda_4>0$ such that
for ${\rm d}(x,\partial\Omega)$ small enough, $\Lambda_1 \phi({\rm d}(x,\partial\Omega))\leq 
v(x)\leq \Lambda_2 \phi({\rm d}(x,\partial\Omega))$ and
$|Dv(x)|\leq \Lambda_3\big[{\rm d}(x,\partial\Omega)h(\Lambda_4\phi({\rm d}(x,\partial\Omega)))+\phi({\rm d}(x,\partial\Omega))/{\rm d}(x,\partial\Omega)\big]$, 
being $\phi$ a solution to \eqref{asympt-prob-ii}. On account of formula~\eqref{zerobeh}, we can find two constants $\Theta_1,\Theta_2>0$
such that, for ${\rm d}(x,\partial\Omega)$ small enough
\begin{equation}
	\label{phicontrol}
\Theta_1 {\rm d}(x,\partial\Omega)^{{\frac{2-2\mu}{1+\gamma-2\mu}}}\leq \phi({\rm d}(x,\partial\Omega))\leq
\Theta_2 {\rm d}(x,\partial\Omega)^{{\frac{2-2\mu}{1+\gamma-2\mu}}},
\end{equation}
which yield in turn
$$
\Lambda_1\Theta_1 {\rm d}(x,\partial\Omega)^{{\frac{2-2\mu}{1+\gamma-2\mu}}}\leq 
v(x)\leq \Lambda_2\Theta_2 {\rm d}(x,\partial\Omega)^{{\frac{2-2\mu}{1+\gamma-2\mu}}}.
$$
Finally, since $g$ is increasing and $u=g(v)$, we have
$$
g\big(\Lambda_1\Theta_1 {\rm d}(x,\partial\Omega)^{{\frac{2-2\mu}{1+\gamma-2\mu}}}\big)\leq 
u(x)\leq g\big(\Lambda_2\Theta_2 {\rm d}(x,\partial\Omega)^{{\frac{2-2\mu}{1+\gamma-2\mu}}}\big).
$$
Finally, using \eqref{gatzero}, we obtain the desired controls on $u$.
Now, from \eqref{phicontrol}, as ${\rm d}(x,\partial\Omega)$ is small,
$$
\phi({\rm d}(x,\partial\Omega))/{\rm d}(x,\partial\Omega)\leq \Theta_2 {\rm d}(x,\partial\Omega)^{-{\frac{\gamma-1}{1+\gamma-2\mu}}}.
$$
On account of \eqref{accat0} and \eqref{zerobeh}, there exists a constant $\Theta_3>0$ such that 
\begin{align*}
& {\rm d}(x,\partial\Omega)h(\Lambda_4\phi({\rm d}(x,\partial\Omega))) =\\
& =\Lambda_4^{(\mu-\gamma)/(1-\mu)}{\rm d}(x,\partial\Omega)
\Big[\frac{h(\Lambda_4\phi({\rm d}(x,\partial\Omega)))}{\Lambda_4^{(\mu-\gamma)/(1-\mu)}
\phi^{(\mu-\gamma)/(1-\mu)}({\rm d}(x,\partial\Omega))}\Big]\phi^{(\mu-\gamma)/(1-\mu)}({\rm d}(x,\partial\Omega)) \\
& \leq \Theta_3{\rm d}(x,\partial\Omega){\rm d}(x,\partial\Omega)^{{\frac{2\mu-2\gamma}{1+\gamma-2\mu}}}=
\Theta_3 {\rm d}(x,\partial\Omega)^{-{\frac{\gamma-1}{1+\gamma-2\mu}}},
\end{align*}
for ${\rm d}(x,\partial\Omega)$ small enough, yielding 
$|Dv(x)|\leq \Lambda_3 (\Theta_2+\Theta_3){\rm d}(x,\partial\Omega)^{-{\frac{\gamma-1}{1+\gamma-2\mu}}}$.
Then, we have
\begin{align*}
|Du(x)| &=g'(v(x))|Dv(x)|=\frac{|Dv(x)|}{\sqrt{a(g(v(x)))}}=\frac{|Dv(x)|}{\sqrt{a(g(v(x)))g^{2\mu}(v(x))}}g^{\mu}(v(x)) &\\
& =\frac{1}{\sqrt{a(g(v(x)))g^{2\mu}(v(x))}}\frac{g^{\mu}(v(x))}{v(x)^{\mu/(1-\mu)}}v(x)^{\mu/(1-\mu)}|Dv(x)|
\leq\omega_1 v(x)^{\mu/(1-\mu)}|Dv(x)| \\
\noalign{\vskip4pt}
&\leq \omega_2{\rm d}(x,\partial\Omega)^{{\frac{2\mu}{1+\gamma-2\mu}}}{\rm d}(x,\partial\Omega)^{-{\frac{\gamma-1}{1+\gamma-2\mu}}}
=\omega_2{\rm d}(x,\partial\Omega)^{{\frac{1-\gamma+2\mu}{1+\gamma-2\mu}}}.
\end{align*}
for some $\omega_1,\omega_2>0$. In particular, if $1<\gamma\leq 1+2\mu$, it follows that $u$
is Lipschitz continuous up the boundary. If instead $\gamma>1+2\mu$,
by the above estimates for $u$ and $|Du|$, we find $\Theta_4>0$ such that
\begin{align*}
|D u^{\frac{1+\gamma-2\mu}{2}}(x)|& =\frac{1+\gamma-2\mu}{2}u^\frac{\gamma-1-2\mu}{2}(x)|Du(x)| \\
& \leq \Theta_4 {\rm d}(x,\partial\Omega)^{{\frac{\gamma-1-2\mu}{1+\gamma-2\mu}}}{\rm d}(x,\partial\Omega)^{{\frac{1-\gamma+2\mu}{1+\gamma-2\mu}}}
=\Theta_4,
\end{align*}
whenever ${\rm d}(x,\partial\Omega)$ is small enough. In turn, since $u^{\frac{1+\gamma-2\mu}{2}}$
is Lipschitz continuous, $0<2/(1+\gamma-2\mu)<1$ and $u=(u^{(1+\gamma-2\mu)/2})^{2/(1+\gamma-2\mu)}$ it
follows that $u$ is H\"older continuous up to the boundary $\partial\Omega$ with exponent $2/(1+\gamma-2\mu)$,
as desired.
Finally, concerning the Sobolev regularity of the solution $u$, observe that in light of 
\cite[Theorem 1.3-J2]{zhangcheng}, a necessary and sufficient condition for
$v$ to belong to $H^1_0(\Omega)$ is that
$$
\lim_{s\to 0^+}\int_s^1 \phi(\xi)h(\phi(\xi))d\xi<+\infty,
$$
and this, since by \eqref{accat0} and \eqref{zerobeh} 
$ \phi(\tau)h(\phi(\tau))\sim \tau^{\frac{2-2\gamma}{1+\gamma-2\mu}}$ as $\tau\to 0^+$, is satisfied
if and only if $\gamma<3-2\mu$. In turn, $u=g(v)\in H^1_0(\Omega)$ if $\gamma<3-2\mu$ since
$g$ is Lipschitz continuous on $(0,+\infty)$ being $a$ bounded away from zero. This concludes the proof of the theorem. \qed

